/* From Uiverse.io by ozgeozkaraa01 - Tags: input, input effect , hover input  */
.__UIV_SCOPE__ .group {
  display: flex;
  line-height: 30px;
  align-items: center;
  position: relative;
  max-width: 200px;
}

.__UIV_SCOPE__ .input {
  width: 100%;
  height: 45px;
  line-height: 30px;
  padding: 0 5rem;
  padding-left: 3rem;
  border: 2px solid transparent;
  border-radius: 10px;
  outline: none;
  background-color: #f8fafc;
  color: #0d0c22;
  transition: .5s ease;
}

.__UIV_SCOPE__ .input::placeholder {
  color: #94a3b8;
}

.__UIV_SCOPE__ .input:focus, .__UIV_SCOPE__ input:hover {
  outline: none;
  border-color: rgba(129, 140, 248);
  background-color: #fff;
  box-shadow: 0 0 0 5px rgb(129 140 248 / 30%);
}

.__UIV_SCOPE__ .icon {
  position: absolute;
  left: 1rem;
  fill: none;
  width: 1rem;
  height: 1rem;
}
